#ifndef KITE_WIND_PROTO_SAMPLE_H
#define KITE_WIND_PROTO_SAMPLE_H

// AI: below section was generated by an AI
// Minimal protobuf writer for version-2 render samples. Host tests use it for valid, malformed
// and over-limit input. Not used in firmware builds.

#include <stddef.h>
#include <stdint.h>

namespace KiteWindProtoSample {

struct Writer {
  uint8_t* data;  // null: count bytes only
  size_t cap;
  size_t length;
  bool ok;
};

inline void put(Writer& w, uint8_t b) {
  if (!w.data) { w.length++; return; }
  if (w.length < w.cap) w.data[w.length++] = b; else w.ok = false;
}
inline void varint(Writer& w, uint64_t v) {
  do {
    uint8_t b = static_cast<uint8_t>(v & 0x7F);
    v >>= 7;
    put(w, v ? static_cast<uint8_t>(b | 0x80) : b);
  } while (v);
}
inline void number(Writer& w, uint32_t field, uint64_t v) { varint(w, (field << 3) | 0); varint(w, v); }
inline void bytes(Writer& w, uint32_t field, const uint8_t* p, size_t n) {
  varint(w, (field << 3) | 2);
  varint(w, n);
  for (size_t i = 0; i < n; i++) put(w, p[i]);
}
template <typename Body> void message(Writer& w, uint32_t field, Body body) {
  Writer count = {nullptr, 0, 0, true};
  body(count);
  varint(w, (field << 3) | 2);
  varint(w, count.length);
  body(w);
}

// Defaults give the largest valid response: 26 tracks, 256 segments, 51 lamps.
struct Spec {
  uint32_t contract = 2;
  size_t digestLength = 32;
  bool definition = true;
  uint32_t tracks = 26;           // tracks 0 and 1 are constant (off, solid), the rest cosine
  uint32_t segments = 256;
  uint32_t constantSegments = 1;  // segment_count written for track 1
  int32_t countSkew = 0;          // added to the last track's segment_count
  uint32_t curve = 2;             // curve of the animation tracks
  uint32_t duration = 1000;
  uint32_t from = 0;
  uint32_t to = 100;
  uint32_t lamps = 51;
  uint32_t firstPixel = 1;
  bool duplicatePixel = false;
  uint32_t track = 2;             // track of every lamp
  uint32_t rgb = 0xFFFFFF;
  uint32_t weather = 2;
  uint32_t brightness = 255;
  uint8_t digestSeed = 0;         // non-zero: digest bytes differ from the default
};

inline uint32_t segmentsOf(const Spec& s, uint32_t track) {
  if (track == 0) return 1;
  if (track == 1) return s.constantSegments;
  const uint32_t animated = s.tracks - 2;
  const uint32_t rest = s.segments - 1 - s.constantSegments;
  return rest / animated + (track - 2 < rest % animated ? 1 : 0);
}

// Returns the encoded length, or 0 when `cap` is too small. Needs s.tracks >= 3.
inline size_t build(const Spec& s, uint8_t* out, size_t cap) {
  Writer w = {out, cap, 0, true};
  number(w, 1, s.contract);
  uint8_t digest[40];
  for (size_t i = 0; i < sizeof(digest); i++) digest[i] = static_cast<uint8_t>(0xA5 ^ i ^ s.digestSeed);
  if (s.digestLength) bytes(w, 2, digest, s.digestLength);
  if (s.definition) {
    message(w, 3, [&s](Writer& d) {
      for (uint32_t t = 0; t < s.tracks; t++) {
        message(d, 1, [&s, t](Writer& m) {
          number(m, 1, t < 2 ? 0 : s.curve);
          int64_t count = segmentsOf(s, t);
          if (t == s.tracks - 1) count += s.countSkew;
          number(m, 2, static_cast<uint64_t>(count));
        });
      }
      for (uint32_t i = 0; i < s.segments; i++) {
        message(d, 2, [&s, i](Writer& m) {
          number(m, 1, s.duration);
          number(m, 2, i == 0 ? 0 : s.from);
          number(m, 3, i == 0 ? 0 : s.to);
        });
      }
    });
  }
  for (uint32_t i = 0; i < s.lamps; i++) {
    message(w, 4, [&s, i](Writer& m) {
      number(m, 1, s.duplicatePixel && i == 1 ? s.firstPixel : s.firstPixel + i);
      number(m, 2, s.track);
      number(m, 3, s.rgb);
    });
  }
  number(w, 5, s.weather);
  number(w, 6, s.brightness);
  return w.ok ? w.length : 0;
}

}  // namespace KiteWindProtoSample
// AI: end

#endif
